		return "h5";
		// #endif
		// #ifdef MP-WEIXIN
		return "mp-weixin";
		// #endif
		// #ifdef MP-ALIPAY
		return "mp-alipay";
		// #endif
		// #ifdef MP-BAIDU
		return "mp-baidu";
		// #endif
		// #ifdef MP-TOUTIAO
		return "mp-toutiao";
		// #endif
		// #ifdef MP-QQ
		return "mp-qq";
		// #endif
		// #ifdef APP-PLUS
		return "app-plus";
